def check_condition(n):
    """Checks if for all k coprime to n, k^2 is congruent to 1 mod n."""
    for k in range(1, n):
        import math
        if math.gcd(k, n) == 1:
            if (k * k) % n != 1:
                print(f"Failed for n={n} with k={k}: k^2={k*k}, which is {k*k % n} mod {n}")
                return False
    print(f"Passed for n={n}")
    return True

# Test cases based on analysis
test_cases = [2, 3, 4, 6, 8, 12, 24, 16]

for n in test_cases:
    check_condition(n)
